<template><div class="page-shell"><div class="page-title-row"><div><h1 class="page-title">用户与权限管理</h1><p class="page-subtitle">区分市级调度指挥员、节点管理员和系统管理员，节点管理员仅维护授权节点数据</p></div></div><CrudManager title="系统用户" endpoint="/users" :columns="columns" :fields="fields" :defaults="{role:'NODE_MANAGER',enabled:true,managedNodeIds:[]}"/></div></template>
<script setup>
import { onMounted,ref } from 'vue';import api from '../api/client';import CrudManager from '../components/CrudManager.vue';const nodes=ref([]);onMounted(async()=>nodes.value=await api.get('/nodes'));const columns=[{prop:'username',label:'登录账号'},{prop:'realName',label:'姓名'},{prop:'role',label:'角色',tag:true},{prop:'enabled',label:'状态',tag:true},{prop:'managedNodeIds',label:'授权节点数',formatter:v=>`${v?.length||0} 个`}];const fields=[{prop:'username',label:'登录账号',required:true},{prop:'password',label:'密码（编辑时留空则不修改）',type:'password'},{prop:'realName',label:'姓名',required:true},{prop:'role',label:'角色',type:'select',options:[{value:'ADMIN',label:'系统管理员'},{value:'DISPATCHER',label:'市级调度指挥员'},{value:'NODE_MANAGER',label:'节点管理员'}],required:true},{prop:'managedNodeIds',label:'授权节点',type:'select',multiple:true,wide:true,options:()=>nodes.value.map(n=>({value:n.id,label:n.name}))},{prop:'enabled',label:'是否启用',type:'switch'}];
